CREATE TYPE "orders_status" AS ENUM (
  'created',
  'running',
  'done',
  'failure'
);

CREATE TYPE "product status" AS ENUM (
  'Out of Stock',
  'In Stock'
);

CREATE TABLE "orders" (
  "id" SERIAL PRIMARY KEY,
  "user_id" int UNIQUE NOT NULL,
  "status" orders_status,
  "created_at" varchar,
  "modified_at" timestamp(2)
);

CREATE TABLE "order_items" (
  "order_id" int,
  "product_id" int,
  "quantity" int DEFAULT 1,
  "created_at" timestamp,
  "modified_at" time
);

CREATE TABLE "products" (
  "id" int,
  "name" varchar,
  "merchant_id" int NOT NULL,
  "price" int,
  "status" "product status",
  "created_at" datetime DEFAULT (now()),
  "modified_at" timestamp,
  PRIMARY KEY ("id", "name")
);

CREATE TABLE "users" (
  "id" int PRIMARY KEY,
  "full_name" varchar,
  "email" varchar UNIQUE,
  "gender" varchar,
  "date_of_birth" varchar,
  "created_at" varchar,
  "modified_at" time(2),
  "country_code" int
);

CREATE TABLE "merchants" (
  "id" int PRIMARY KEY,
  "merchant_name" varchar,
  "country_code" int,
  "created_at" varchar,
  "modified_at" time,
  "admin_id" int
);

CREATE TABLE "countries" (
  "code" int PRIMARY KEY,
  "name" varchar,
  "continent_name" varchar
);

CREATE TABLE "foo" (
  "bar" text[],
  "bar2" int[1],
  "bar3" int[2][3],
  "bar4" int[],
  "bar5" int[2],
  "bar6" text[8],
  "bar7" text[100],
  "bar8" time(2)[],
  "bar9" time(1)[1],
  "bar10" time(1)[],
  "bar11" time[5],
  "bar12" timestamp(2)[10][2][5],
  "bar13" "character varying[]",
  "bar14" "character varying(25)[][2][]",
  "bar15" "character varying[76]"
);

CREATE TABLE "accounts" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "domain" "character varying(100)",
  "name" "character varying(100)",
  "slug" "character varying(10)",
  PRIMARY KEY ("id")
);

CREATE TABLE "tests" (
  "id" bigint NOT NULL,
  "type" character varying DEFAULT ('testing'::charactervarying)
);

CREATE TABLE "users2" (
  "username" character varying NOT NULL,
  "hashed_password" character varying NOT NULL,
  "full_name" character varying NOT NULL,
  "email" character varying NOT NULL,
  "password_changed_at" timestamp NOT NULL DEFAULT ('0001-01-01 00:00:00+00'::timestampwithtimezone),
  "created_at" timestamp NOT NULL DEFAULT (now())
);

CREATE TABLE "table1" (
  "field" text NOT NULL,
  "field2" text NOT NULL,
  PRIMARY KEY ("field", "field2")
);

CREATE TABLE "table2" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "field" text,
  "field2" text
);

CREATE TABLE "test_table" (
  "name" varchar NOT NULL,
  "id" varchar,
  "linked_name" varchar NOT NULL,
  PRIMARY KEY ("name", "id")
);

CREATE INDEX "product_status" ON "products" ("merchant_id", "status");

CREATE UNIQUE INDEX ON "products" USING HASH ("id");

COMMENT ON TABLE "products" IS 'Products table comment';

COMMENT ON TABLE "users" IS 'Store user data';

ALTER TABLE "order_items" ADD FOREIGN KEY ("order_id") REFERENCES "orders" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "order_items" ADD FOREIGN KEY ("product_id") REFERENCES "products" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "users" ADD FOREIGN KEY ("country_code") REFERENCES "countries" ("code") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "merchants" ADD FOREIGN KEY ("country_code") REFERENCES "countries" ("code") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "products" ADD FOREIGN KEY ("merchant_id") REFERENCES "merchants" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "merchants" ADD FOREIGN KEY ("admin_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "table2" ADD FOREIGN KEY ("field", "field2") REFERENCES "table1" ("field", "field2") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "test_table" ADD CONSTRAINT "test_table_fk" FOREIGN KEY ("linked_name", "id") REFERENCES "test_table" ("name", "id") DEFERRABLE INITIALLY IMMEDIATE;
